"""Render all completed diagnostics; no model or scoring-rule selection."""
import json
from common import ROOT

def main():
 r=json.loads((ROOT/'metrics/results.json').read_text());assert r['completed'];v=json.loads((ROOT/'metrics/artifact_verification.json').read_text());kernel=json.loads((ROOT/'metrics/chunked_delta_verification.json').read_text());assert v['status']==kernel['status']=='passed';arch=json.loads((ROOT/'metrics/architecture_audit.json').read_text());unc=json.loads((ROOT/'metrics/uncertainty.json').read_text())['results'];text=[]
 text.append('# FlyGraph: завершённая диагностика после EXT3\n')
 text.append('За дополнительное окно выполнены замороженные проверки EXT2/EXT3 и обучение диагностических линейных readout-слоёв. **Новых optimizer-шагов нейросети здесь0.** Это не ещё один FT и не новая генеративная модель. Основной EXT3 уже завершил768/768 новых шагов; его веса и результаты не изменены. Диагностика завершилась '+r['end_utc']+f', {r["wall_seconds"]/60:.2f}мин CPU.\n')
 text.append('Главный вывод: признаки позволяют запомнить небольшую обучающую выборку, но линейный readout не переносится на новые вопросы. Изменение scoring помогает отдельным случаям PIQA, однако общего подтверждённого улучшения нет. Полное отсутствие знаний эти проверки не доказывают: последняя hidden-state и линейный слой ограничивают доступ к информации.\n')
 text.append('**Все заранее фиксированные scoring-правила на новом test.** В каждой ячейке правильных/64; одинаковые исходные вопросы и варианты для обоих frozen checkpoint. Генерация — greedy16 по полному словарю. Scoring полного ответа — отдельный teacher-forced diagnostic с одинаковыми внешними текстами для двух моделей, не генерация и не сравнение с API.\n')
 for arm in ['EXT2','EXT3']:
  text.append('**'+arm+'**\n\n| Метод | OpenBookQA | PIQA | ARC Challenge |\n|---|---:|---:|---:|')
  tasks=r['scoring'][arm]['test_mcq']
  for method in next(iter(tasks.values()))['methods']:
   text.append('| '+method+' | '+' | '.join(str(tasks[t]['methods'][method]['correct'])+'/64' for t in ['openbookqa','piqa','arc_challenge'])+' |')
  text.append('')
 text.append('`answer_mean/sum` — log probability полного оригинального текста варианта без EOS, mean по его токенам либо сумма. `calibrated` вычитает вероятность того же ответа без вопроса. Варианты неодинаковой длины не обрезаются; длины сохранены. `answer_without_question_mean` — контроль без вопроса, не новая задача. Ни один метод не выбран победителем по test, все результаты опубликованы.\n')
 text.append('**Что проверка объясняет.** Для EXT3 FP32/BF16 расходятся в26/192 predicted labels (9/8/9 по задачам), но FP32 даёт16/30/16 против17/34/16 у BF16. Это чувствительность близких scores к округлению, а не исправление низкой семантической точности. На трёх внешних dev-примерах target alignment/full-vs-cache проверка прошла; это ограниченная инженерная проверка, не доказательство отсутствия любого бага.\n')
 pi=unc['EXT3']['test_mcq']['piqa']['answer_calibrated_mean'];text.append(f"Калиброванный mean на PIQA:41/64=64.06%, Wilson95%[{100*pi['wilson95'][0]:.2f};{100*pi['wilson95'][1]:.2f}]%. Разница с буквенным BF16 scoring +10.94п.п., paired bootstrap95%[{100*pi['paired_bootstrap95'][0]:.2f};{100*pi['paired_bootstrap95'][1]:.2f}]п.п. Интервал разницы включает0; проверялось несколько методов, multiplicity correction не применялась, вывод exploratory. На OBQA калибровка ухудшает17→12/64, ARC16→18/64. Это не основание объявить новое общее улучшение или внедрить правило, подобранное по test.\n")
 text.append('При answer_mean удаление вопроса меняет только9/192 выбранных ответов EXT3 (1 OBQA,2 PIQA,6 ARC). У EXT2 —10/192. В этом формате сильно влияют априорные вероятности ответов. Суммирование/калибровка может менять этот эффект, поэтому утверждать, что модель совсем не читает вопрос, нельзя.\n')
 text.append('**Контроль известных примеров.** Они намеренно являются частью probe train; это не независимый test.\n\n| Модель / scoring | OBQA | PIQA |\n|---|---:|---:|')
 for arm in ['EXT2','EXT3']:
  for method in ['label_bf16','label_fp32','answer_calibrated_mean']:
   text.append('| '+arm+' / '+method+' | '+' | '.join(str(r['scoring'][arm]['seen_control'][t]['methods'][method]['correct'])+'/32' for t in ['openbookqa','piqa'])+' |')
 text.append('\nВсе остальные seen-control методы также сохранены в results.json/scoring.csv.\n')
 text.append('**Readout из замороженных EXT3 признаков.** Отдельная ridge-регрессия для OBQA и PIQA, по256 уже виденных моделью balanced train-примеров. Lambda выбран только по32 новым dev/task, в обоих случаях10.0; при равенстве accuracy выбиралось большее значение. На ARC использован OBQA-head как transfer-контроль.\n\n| Head/task | Tiny train | Train | Новый dev | Новый test |\n|---|---:|---:|---:|---:|')
 for task,dd in r['probe'].items():
  cells=[str(dd[p+'_correct'])+'/'+str(dd[p+'_n']) if p+'_correct' in dd else '—' for p in ['tiny_train','train']]+[str(dd[p]['correct'])+'/'+str(dd[p]['n']) for p in ['dev_mcq','test_mcq']];text.append('| '+task+' | '+' | '.join(cells)+' |')
 text.append('\nВсе32 tiny-примера интерполированы, train471/512. Test62/192 у readout. Выходной слой способен подогнаться; перенос этих признаков остаётся слабым. Это совместимо с недостаточным семантическим обучением, но также с нелинейным кодированием информации или недостаточностью выбранного readout. Линейные probe не равны generative LLM и не заменяют Qwen/MiniCPM baseline.\n')
 text.append('**Данные и воспроизводимость.** Только опубликованные OpenBookQA, PIQA и ARC из OpenCompassData-core-20240207/release0.2.2.rc1, точный archive/member SHA и оригинальные записи сохранены. Лицензии Apache2/AFL3/CC-BY-SA4 и inherited Alpaca CC-BY-NC4 — в DATA_LICENSES.md. Source/task IDs и seed2026102504 зафиксированы до вывода. Runtime setup seed20261025 явно указан отдельно. Train512, tiny32 и seen64 — намеренные подмножества. Dev96 и test192 не пересекаются по нормализованным вопросам друг с другом, с probe train и с известными EXT2/EXT3 train/dev/test и прежним ARC128. Проверены длинные stems/полные question+choices против известных Alpaca train; совпадений не найдено. Неизвестный исторический pretraining не позволяет гарантировать глобальную decontamination. PIQA test — новый зарезервированный участок официального validation, не скрытый test.\n')
 text.append('Никакие gold-ответы/вопросы не сочинялись. Все фиксированные методы объявлены до inference; тестовые ответы не использовались для выбора checkpoint или lambda. Сохранены сырые scores, generations, IDs, features, native float64 coefficients, CSV/JSON и10,000-replicate интервалы. Все четыре readout-head (main+tiny) заново вычислены из опубликованных features **побитово идентично**,288 dev/test predictions воспроизведены. Для closed-form ridge нет optimizer/RNG/sampler-state, который можно было бы честно выдать за neural resume.\n')
 maxlog=max(x['logits']['max_abs'] for x in kernel['forward_cache']);maxgrad=max(x['max_abs'] for x in kernel['gradient_fixture']['checks'].values())
 text.append(f'**Применённая инженерная идея.** Отдельная optional chunk64 реализация существующего delta сохраняет формы весов и FP32 state. На4 внешних dev prompts (103–371токен) максимальная ошибка logits{maxlog:.3g}; cached next-token одинаков, все состояния прошли допуск. Градиенты всех135 тензоров на128-токенном dev-префиксе прошли, max abs{maxgrad:.3g}. Это проверка float32; BF16/GPU и длинные2048 контексты отдельно здесь не проверялись. Измерения времени единичные, ускорение не заявлено. Native EXT3 kernel не заменён, тренировочные веса не менялись. См. ENGINEERING_REGISTRATION.md и chunked_delta_verification.json.\n')
 text.append('**Архитектура и следующий шаг.** ARCHITECTURE_PLAN_RU.md сопоставляет реальные100,028,328 параметров с первоисточниками Qwen, Kimi, MiniCPM, SmolLM2/MobileLLM и Muon. Подсчёт альтернатив193.76M/287.50M выполнен только на meta-device; их обучение не запускалось. В текущем tokenizer79–84% byte fallback на новых dev текстах, хотя roundtrip точный. Приоритет — проверяемая смесь опубликованных текстовых ответов/коротких объяснений и continued language training; затем отдельный WSD/optimizer test. Изменения vocab/width/KDA/MLA не выдаются за checkpoint-compatible улучшение.\n')
 text.append('**Итог всего окна.** EXT3:768 новых optimizer updates, selected640 только по dev, independent test OBQA29/128, PIQA66/128, ARC29/128. Отличие от EXT2 +0.26п.п.,95%[-6.25;+6.77], улучшение не подтверждено. Эти прежние результаты не объединены с новым diagnostic test и не выданы за свежий FT. Exact Qwen3.5-0.8B и openbmb/MiniCPM-V-4.7-1B не запущены: прежние поддерживаемые запросы в этой среде завершились tunnel403. В diagnostics повторных запросов0, замен моделей и обходов0. Цель общего превосходства остаётся недостигнутой.\n')
 text.append('Новые readout-веса/feature-файлы меньше90MB каждый. Полные native EXT3 weights/state находятся в ранее проверенных ordinary Git parts; PARENT_CHECKPOINTS.json содержит immutable commits и SHA, старые байты не перепакованы. Команды — REPRODUCE.md. Статус публикации подтверждается только PUBLICATION.json/PUSH_COMPLETE.json, а не наличием этого отчёта.\n')
 (ROOT/'REPORT_RU.md').write_text('\n'.join(text));print('REPORT_WRITTEN')
if __name__=='__main__':main()
